import numpy as np
from scipy import sparse
from scipy.sparse import linalg as sla


class _FastOp(sla.LinearOperator):
    def __init__(self, A):
        self._A = A
        super().__init__(dtype=A.dtype, shape=A.shape)

    def _matvec(self, x):
        return self._A._matmul_vector(x)


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        N = A.shape[0]
        v0 = np.ones(N, dtype=A.dtype)
        op = _FastOp(A)
        eigenvalues, eigenvectors = sla.eigs(
            op, k=k, v0=v0, maxiter=N * 200, ncv=max(2 * k + 1, 20),
        )
        pairs = list(zip(eigenvalues, eigenvectors.T))
        pairs.sort(key=lambda pair: -np.abs(pair[0]))
        return [pair[1] for pair in pairs]

